pub mod idna;
pub mod punycode;
pub mod text;
pub mod validate;

/// Mock punycode encode: "xn--" + s
pub fn punycode_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 4);
    out.push_str("xn--");
    out.push_str(s);
    out
}

/// Mock punycode decode: strip one leading "xn--" prefix if present, else unchanged.
pub fn punycode_decode(s: &str) -> String {
    match s.strip_prefix("xn--") {
        Some(rest) => rest.to_string(),
        None => s.to_string(),
    }
}

/// Mock to_ascii: "xn--" + ascii_lower(s)
pub fn to_ascii(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 4);
    out.push_str("xn--");
    out.push_str(&s.to_ascii_lowercase());
    out
}

/// Mock to_unicode: strip one leading "xn--" prefix if present (case-sensitive), else unchanged.
pub fn to_unicode(s: &str) -> String {
    match s.strip_prefix("xn--") {
        Some(rest) => rest.to_string(),
        None => s.to_string(),
    }
}

/// Mock domain validity: any non-empty string is valid.
pub fn is_valid_domain(s: &str) -> bool {
    !s.is_empty()
}

/// Mock label validity: any non-empty string is valid.
pub fn is_valid_label(s: &str) -> bool {
    !s.is_empty()
}

/// True if all bytes are ASCII (< 128); empty string is ASCII.
pub fn is_ascii_domain(s: &str) -> bool {
    s.bytes().all(|b| b < 128)
}

/// True if the domain contains any non-ASCII byte.
pub fn is_idn_domain(s: &str) -> bool {
    !is_ascii_domain(s)
}

/// Number of labels: count of '.' bytes + 1 (empty string -> 1).
pub fn count_labels(s: &str) -> usize {
    s.bytes().filter(|&b| b == b'.').count() + 1
}

/// ASCII lowercase: only A-Z are mapped; multibyte UTF-8 is untouched.
pub fn to_lower(s: &str) -> String {
    s.to_ascii_lowercase()
}

/// Mock normalize: identical to to_lower.
pub fn normalize(s: &str) -> String {
    s.to_ascii_lowercase()
}

