mod idna;
#[path = "src/validate.rs"]
mod validate;
#[path = "src/text.rs"]
mod text;

fn as_int(b: bool) -> u8 {
    if b {
        1
    } else {
        0
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let inputs: Vec<String> = if args.is_empty() {
        vec![
            "one".to_string(),
            "two.three".to_string(),
            "four.five.six".to_string(),
        ]
    } else {
        args
    };

    for input in &inputs {
        println!(
            "{} {} {} {} {} {} {} {} {} {} {}",
            idna::to_ascii(input),
            idna::to_unicode(input),
            punycode::punycode_encode(input),
            punycode::punycode_decode(input),
            as_int(validate::is_valid_domain(input)),
            as_int(validate::is_valid_label(input)),
            as_int(validate::is_ascii_domain(input)),
            as_int(validate::is_idn_domain(input)),
            text::to_lower(input),
            text::normalize(input),
            validate::count_labels(input)
        );
    }
}

/// Mock punycode encode: "xn--" + s
pub fn punycode_encode(s: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len() + 4);
    out.extend_from_slice(b"xn--");
    out.extend_from_slice(s);
    out
}

/// Mock punycode decode: strip one leading "xn--" prefix if present, else unchanged.
pub fn punycode_decode(s: &[u8]) -> Vec<u8> {
    match s.strip_prefix(b"xn--") {
        Some(rest) => rest.to_vec(),
        None => s.to_vec(),
    }
}

/// Mock to_ascii: "xn--" + ascii_lower(s)
pub fn to_ascii(s: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len() + 4);
    out.extend_from_slice(b"xn--");
    out.extend_from_slice(&s.to_ascii_lowercase());
    out
}

/// Mock to_unicode: strip one leading "xn--" prefix if present (case-sensitive), else unchanged.
pub fn to_unicode(s: &[u8]) -> Vec<u8> {
    match s.strip_prefix(b"xn--") {
        Some(rest) => rest.to_vec(),
        None => s.to_vec(),
    }
}

/// Mock domain validity: non-empty and at most 255 bytes (dots included).
pub fn is_valid_domain(s: &[u8]) -> bool {
    !s.is_empty() && s.len() <= 255
}

/// Mock label validity: non-empty and at most 63 bytes.
pub fn is_valid_label(s: &[u8]) -> bool {
    !s.is_empty() && s.len() <= 63
}

/// True if all bytes are ASCII (< 128); empty string is ASCII.
pub fn is_ascii_domain(s: &[u8]) -> bool {
    s.iter().all(|&b| b < 128)
}

/// True if the domain contains any non-ASCII byte.
pub fn is_idn_domain(s: &[u8]) -> bool {
    !is_ascii_domain(s)
}

/// Number of labels: count of '.' bytes + 1 (empty string -> 1).
pub fn count_labels(s: &[u8]) -> usize {
    s.iter().filter(|&&b| b == b'.').count() + 1
}

/// ASCII lowercase: only A-Z are mapped; all other bytes (including
/// multibyte UTF-8 and non-UTF-8 bytes) are untouched.
pub fn to_lower(s: &[u8]) -> Vec<u8> {
    s.to_ascii_lowercase()
}

/// Mock normalize: identical to to_lower.
pub fn normalize(s: &[u8]) -> Vec<u8> {
    s.to_ascii_lowercase()
}

#[path = "src/punycode.rs"]
mod punycode;
#[path = "src/idna.rs"]
mod idna;
#[path = "src/validate.rs"]
mod validate;
#[path = "src/text.rs"]
mod text;

use std::io::Write;
use std::os::unix::ffi::OsStrExt;

fn as_byte(b: bool) -> &'static [u8] {
    if b {
        b"1"
    } else {
        b"0"
    }
}

fn main() {
    let args: Vec<Vec<u8>> = std::env::args_os()
        .skip(1)
        .map(|a| a.as_bytes().to_vec())
        .collect();
    let inputs: Vec<Vec<u8>> = if args.is_empty() {
        vec![
            b"one".to_vec(),
            b"two.three".to_vec(),
            b"four.five.six".to_vec(),
        ]
    } else {
        args
    };

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    for input in &inputs {
        let fields: Vec<Vec<u8>> = vec![
            idna::to_ascii(input),
            idna::to_unicode(input),
            punycode::punycode_encode(input),
            punycode::punycode_decode(input),
            as_byte(validate::is_valid_domain(input)).to_vec(),
            as_byte(validate::is_valid_label(input)).to_vec(),
            as_byte(validate::is_ascii_domain(input)).to_vec(),
            as_byte(validate::is_idn_domain(input)).to_vec(),
            text::to_lower(input),
            text::normalize(input),
            validate::count_labels(input).to_string().into_bytes(),
        ];
        let mut line = Vec::new();
        for (i, field) in fields.iter().enumerate() {
            if i > 0 {
                line.push(b' ');
            }
            line.extend_from_slice(field);
        }
        line.push(b'\n');
        out.write_all(&line).unwrap();
    }
}
